use vstd::prelude::*;

verus! {

fn imag(val: Vec<(f64, f64)>) -> Vec<f64>
    ensures
        // The output has the same length as the input
        result.len() == val.len(),
        // For every index i, result[i] equals the imaginary part of val[i]
        forall |i: usize| i < val.len() ==> result[i] == val[i].1,
        // If the imaginary part is zero, the output is zero
        forall |i: usize| i < val.len() && val[i].1 == 0.0 ==> result[i] == 0.0,
        // If the input pair is non‐zero, the output still equals the imaginary part
        forall |i: usize|
            i < val.len() &&
            (val[i].0 != 0.0 || val[i].1 != 0.0)
            ==> result[i] == val[i].1,
{
    // Build a new vector of capacity equal to the input length
    let mut result: Vec<f64> = Vec::with_capacity(val.len());
    let mut i: usize = 0;

    // Loop over all indices, pushing val[i].1 into result
    while i < val.len()
        invariant i <= val.len()
        invariant result.len() == i
        invariant forall |j: usize| j < i ==> result[j] == val[j].1
        decreases val.len() - i
    {
        let imag_part = val[i].1;
        result.push(imag_part);
        i = i + 1;
    }

    result
}

} // end of verus! 

